<template>
  <main class="audit-page"><header><div><h1>操作审计</h1><p>记录关键 API 访问、处理状态和耗时，便于安全审计与故障排查。</p></div><div><el-input v-model="path" clearable placeholder="按 API 路径筛选" @keyup.enter="load"/><el-button @click="load">查询</el-button></div></header><section><el-table :data="rows" v-loading="loading" stripe><el-table-column prop="createdAt" label="时间" width="180"/><el-table-column prop="username" label="用户" width="120"/><el-table-column prop="requestMethod" label="方法" width="80"/><el-table-column prop="requestPath" label="API 路径" min-width="260" show-overflow-tooltip/><el-table-column prop="statusCode" label="状态码" width="80"><template #default="{row}"><el-tag :type="row.statusCode<400?'success':'danger'">{{row.statusCode}}</el-tag></template></el-table-column><el-table-column prop="durationMs" label="耗时（毫秒）" width="120"/><el-table-column prop="clientIp" label="客户端 IP" width="150"/></el-table><el-pagination v-model:current-page="page" :page-size="size" :total="total" layout="total, prev, pager, next" @current-change="load"/></section></main>
</template>
<script setup>import{onMounted,ref}from'vue';import{getAuditPage}from'@/api/audit';const rows=ref([]),loading=ref(false),path=ref(''),page=ref(1),size=ref(30),total=ref(0);async function load(){loading.value=true;try{const r=await getAuditPage({page:page.value,size:size.value,path:path.value||undefined});rows.value=r.data?.records||[];total.value=r.data?.total||0}finally{loading.value=false}}onMounted(load);</script>
<style scoped>.audit-page{max-width:1400px;margin:0 auto;padding:32px}.audit-page header{display:flex;justify-content:space-between;gap:16px;align-items:center;margin-bottom:18px}.audit-page header>div:last-child{display:flex;gap:8px}.audit-page h1{margin:0 0 6px}.audit-page p{margin:0;color:#64748b}.audit-page section{padding:18px;background:#fff;border:1px solid #e2e8f0;border-radius:16px}.el-pagination{margin-top:16px;justify-content:flex-end}</style>
